CREATE TYPE "public"."meeting_kind" AS ENUM('midweek', 'weekend');--> statement-breakpoint
CREATE TYPE "public"."meeting_program_status" AS ENUM('draft', 'confirmed');--> statement-breakpoint
CREATE TABLE "meeting_programs" ("id" text PRIMARY KEY NOT NULL,"kind" "meeting_kind" NOT NULL,"week_start" text NOT NULL,"date" text NOT NULL,"outline_id" text,"created_by" text,"status" "meeting_program_status" DEFAULT 'draft' NOT NULL,"created_at" timestamp DEFAULT now() NOT NULL,"updated_at" timestamp DEFAULT now() NOT NULL, CONSTRAINT "meeting_programs_kind_week_start_unique" UNIQUE("kind","week_start"));--> statement-breakpoint
CREATE TABLE "meeting_assignments" ("id" text PRIMARY KEY NOT NULL,"program_id" text NOT NULL,"part_key" text NOT NULL,"section" text DEFAULT '' NOT NULL,"title" text NOT NULL,"subtitle" text DEFAULT '' NOT NULL,"start_time" text DEFAULT '' NOT NULL,"duration_minutes" integer DEFAULT 0 NOT NULL,"person_id" text,"person_name" text DEFAULT '' NOT NULL,"helper_person_id" text,"helper_person_name" text DEFAULT '' NOT NULL,"song_number" integer,"song_theme" text DEFAULT '' NOT NULL,"sort_order" integer DEFAULT 0 NOT NULL,"created_at" timestamp DEFAULT now() NOT NULL);--> statement-breakpoint
ALTER TABLE "meeting_programs" ADD CONSTRAINT "meeting_programs_created_by_users_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "meeting_assignments" ADD CONSTRAINT "meeting_assignments_program_id_meeting_programs_id_fk" FOREIGN KEY ("program_id") REFERENCES "public"."meeting_programs"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "meeting_assignments_program_idx" ON "meeting_assignments" USING btree ("program_id");--> statement-breakpoint
